"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[6221],{50694:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[],"name":"ControlsData","desc":"Single source of truth for every gamepad bind in the game (and the\\nkeyboard keys that mirror gamepad-first actions). Feature code requires\\nthis instead of inlining `Enum.KeyCode.Button*` literals so the whole\\ncontroller layout is auditable in one place \u2014 and so a new bind can be\\nchecked against the budget below before it ships.\\n\\nKeyboard-first keys that predate this file (reload R, drop G, quick-buy\\nZ/X/C + B/N/M, arena packs H/J/K, tier T, hotbar 1-0) stay declared in\\ntheir feature files; only their gamepad twins live here.\\n\\nGamepad button budget (keep in sync when editing):\\n- A: vehicle exit / GUI activate (engine); game-over continue (bound\\n  only while the run-end takeover is on screen)\\n- B: modal close, RV repair (guarded), arena pack 3 (L1 chord), queue\\n  leave (B = \\"back out\\" \u2014 modals sink B first, so an open modal closes\\n  before a second press leaves the queue)\\n- X: reload, queue vote-skip, arena pack 1 (L1 chord)\\n- Y: drop weapon, queue mode toggle (lobby picker), arena pack 2 (L1\\n  chord)\\n- L1: chord modifier (quick-buy upgrades, arena packs, inventory)\\n- L2: melee, trap rotate (priority-gated pair)\\n- L3: sprint\\n- R1: hotbar cycle (bare), settings toggle (L1 chord, console only)\\n- R2: shoot, consumable use, trap place, vehicle gas (context-gated)\\n- R3: arena auto-skip toggle (level)\\n- DPad L/U/R: quick-buy slots (bare = traps, L1 = upgrades); queue\\n  party size 1/2/3 while the lobby picker shows\\n- DPad Down: buy weapon tier; inventory toggle (L1 chord); queue party\\n  size 4 while the lobby picker shows; focus the lobby side menu (bare,\\n  main place, not queued \u2014 disjoint from every other DPadDown role)\\n- DPad Up also = PLAY (join best queue) in the lobby while NOT queued \u2014\\n  disjoint from its size-2 role, which only exists while queued\\n- Thumbstick2: camera look / auto-aim break / skill tree preview","source":{"line":41,"path":"src/Shared/Data/Core/ControlsData.luau"}}')}}]);